optimization-iteration.patch:
diff --git a/tools/bot-evaluation/src/runner.rs b/tools/bot-evaluation/src/runner.rs
index e2ee6990..3ee8f46d 100644
--- a/tools/bot-evaluation/src/runner.rs
+++ b/tools/bot-evaluation/src/runner.rs
@@ -309,7 +309,7 @@ fn evaluate_inner(c: Config, resume: Option<PathBuf>) -> Result<(i32, PathBuf)>
             }
             record["games"]["game"][index] = result.neutral.clone();
             for (i, report) in reports.iter_mut().enumerate() {
-                report["games"]["game"][index] = result.records[i].clone();
+                report["games"]["game"][index] = std::mem::take(&mut result.records[i]);
             }
             finish(&mut record);
             if result.neutral["status"] == "completed" {
@@ -336,9 +336,6 @@ fn evaluate_inner(c: Config, resume: Option<PathBuf>) -> Result<(i32, PathBuf)>
             let write_ms = write_start.elapsed().as_secs_f64() * 1000.0;

             // This full-path latency includes mandatory XML serialization, XSD validation and durable writes.
-            for r in &mut result.records {
-                r["result"]["duration_ms"] = json!(result.elapsed + write_ms);
-            }
             for report in &mut reports {
                 report["games"]["game"][index]["result"]["duration_ms"] =
                     json!(result.elapsed + write_ms);
